{"file":"src/cart.js","explanation":"The applyDiscount function was incorrectly multiplying the amount by the whole-number percentage instead of dividing by 100 to calculate the discount.","content":"// Small shopping-cart helpers used by the checkout page.
function subtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

// percent is given as a whole number: 10 means 10 %
function applyDiscount(amount, percent) {
  return amount - (amount * percent / 100);
}

function total(items, percent = 0) {
  return applyDiscount(subtotal(items), percent);
}

module.exports = { subtotal, applyDiscount, total };"}
